// Config plugin for Android release builds (feature 010, constitution "Builds Móviles de Release").
// mobile/android/ is generated by `expo prebuild`, so every change to it lives here. Only the
// variable names are written to the generated files: Gradle reads the values when it builds.

const { withAppBuildGradle, withGradleProperties } = require("expo/config-plugins");

const MARKER = "// chepagame-release-signing";

const PROJECT_ROOT_LINE = /^def projectRoot = .*$/m;
const DEBUG_SIGNING_CONFIG = /(signingConfigs\s*\{\s*debug\s*\{[^}]*\})/;
const RELEASE_BUILD_TYPE_DEBUG_KEY =
  /(buildTypes\s*\{[\s\S]*?\brelease\s*\{[^}]*?)signingConfig signingConfigs\.debug/;

// Groovy, inserted after `def projectRoot` (mobile/). Environment variables win over mobile/.env.
const LOAD_SIGNING = [
  "",
  `${MARKER}: managed by plugins/withReleaseSigning.js (feature 010).`,
  "// Release builds are signed with the project's upload key, read from the environment or from",
  "// mobile/.env. Without it, release packaging fails instead of falling back to the debug key.",
  "def releaseSigning = { ->",
  '    def keys = ["ANDROID_UPLOAD_STORE_FILE", "ANDROID_UPLOAD_STORE_PASSWORD", "ANDROID_UPLOAD_KEY_ALIAS", "ANDROID_UPLOAD_KEY_PASSWORD"]',
  "    def fromFile = [:]",
  '    def envFile = new File(projectRoot, ".env")',
  "    if (envFile.isFile()) {",
  "        envFile.eachLine { line ->",
  "            def text = line.trim()",
  '            if (!text || text.startsWith("#") || !text.contains("=")) return',
  '            def index = text.indexOf("=")',
  "            def value = text.substring(index + 1).trim()",
  "            if (value.length() >= 2 && (value[0] == '\"' || value[0] == \"'\") && value[-1] == value[0]) {",
  "                value = value.substring(1, value.length() - 1)",
  "            }",
  "            fromFile[text.substring(0, index).trim()] = value",
  "        }",
  "    }",
  "    def values = [:]",
  "    keys.each { key -> values[key] = System.getenv(key) ?: fromFile[key] }",
  "    def missing = keys.findAll { !values[it] }",
  "    if (values.ANDROID_UPLOAD_STORE_FILE && !new File(values.ANDROID_UPLOAD_STORE_FILE).isFile()) {",
  '        missing << "ANDROID_UPLOAD_STORE_FILE (file not found)"',
  "    }",
  "    return [values: values, missing: missing, ready: missing.isEmpty()]",
  "}.call()",
  "",
  "gradle.taskGraph.whenReady { graph ->",
  '    def packagesRelease = graph.allTasks.any { it.name in ["packageRelease", "bundleRelease"] }',
  "    if (packagesRelease && !releaseSigning.ready) {",
  '        throw new GradleException("Release signing is not configured. Missing: ${releaseSigning.missing.join(\', \')}. See README \\"Android release build\\".")',
  "    }",
  "}",
].join("\n");

const RELEASE_SIGNING_CONFIG = [
  "",
  "        release {",
  "            if (releaseSigning.ready) {",
  "                storeFile file(releaseSigning.values.ANDROID_UPLOAD_STORE_FILE)",
  "                storePassword releaseSigning.values.ANDROID_UPLOAD_STORE_PASSWORD",
  "                keyAlias releaseSigning.values.ANDROID_UPLOAD_KEY_ALIAS",
  "                keyPassword releaseSigning.values.ANDROID_UPLOAD_KEY_PASSWORD",
  "            }",
  "        }",
].join("\n");

function replaceOnce(source, pattern, replacement, what) {
  if (!pattern.test(source)) {
    throw new Error(
      `withReleaseSigning: could not find ${what} in app/build.gradle. ` +
        "The Expo template changed; update plugins/withReleaseSigning.js.",
    );
  }
  return source.replace(pattern, replacement);
}

/** Rewrites app/build.gradle so release builds are signed with the project's own key. */
function applyReleaseSigning(buildGradle) {
  if (buildGradle.includes(MARKER)) return buildGradle;
  let result = replaceOnce(
    buildGradle,
    RELEASE_BUILD_TYPE_DEBUG_KEY,
    // Never the debug key: without the upload key the release config stays unsigned and the
    // whenReady check stops the build.
    "$1signingConfig releaseSigning.ready ? signingConfigs.release : null",
    "the debug key in buildTypes.release",
  );
  result = replaceOnce(
    result,
    DEBUG_SIGNING_CONFIG,
    `$1${RELEASE_SIGNING_CONFIG}`,
    "signingConfigs.debug",
  );
  return replaceOnce(result, PROJECT_ROOT_LINE, `$&\n${LOAD_SIGNING}`, "`def projectRoot`");
}

const RELEASE_PROPERTIES = {
  "android.enableMinifyInReleaseBuilds": "true",
  "android.enableShrinkResourcesInReleaseBuilds": "true",
};

/** Turns on R8 and resource shrinking for release builds. */
function setReleaseGradleProperties(properties) {
  const result = properties.filter(
    (item) => !(item.type === "property" && item.key in RELEASE_PROPERTIES),
  );
  for (const [key, value] of Object.entries(RELEASE_PROPERTIES)) {
    result.push({ type: "property", key, value });
  }
  return result;
}

function withReleaseSigning(config) {
  config = withAppBuildGradle(config, (mod) => {
    if (mod.modResults.language === "groovy") {
      mod.modResults.contents = applyReleaseSigning(mod.modResults.contents);
    }
    return mod;
  });
  return withGradleProperties(config, (mod) => {
    mod.modResults = setReleaseGradleProperties(mod.modResults);
    return mod;
  });
}

module.exports = withReleaseSigning;
module.exports.applyReleaseSigning = applyReleaseSigning;
module.exports.setReleaseGradleProperties = setReleaseGradleProperties;
